class Solution { private val mod=1000000007L;private fun multiply(a:Array<LongArray>,b:Array<LongArray>):Array<LongArray>{val c=Array(2){LongArray(2)};for(i in 0 until 2)for(j in 0 until 2)for(p in 0 until 2)c[i][j]=(c[i][j]+a[i][p]*b[p][j])%mod;return c};private fun power(exponentInput:Long,n:Int):Array<LongArray>{var exponent=exponentInput;var result=arrayOf(longArrayOf(1,0),longArrayOf(0,1));var base=arrayOf(longArrayOf(0,(n-1).toLong()),longArrayOf(1,(n-2).toLong()));while(exponent>0){if(exponent and 1L==1L)result=multiply(result,base);base=multiply(base,base);exponent=exponent shr 1};return result};private fun rotationMatches(s:String,t:String):Int{val n=t.length;val lps=IntArray(n);var i=1;var length=0;while(i<n)if(t[i]==t[length])lps[i++]=++length else if(length>0)length=lps[length-1] else i++;val text=s+s.substring(0,n-1);var matches=0;i=0;var j=0;while(i<text.length)if(text[i]==t[j]){i++;j++;if(j==n){matches++;j=lps[j-1]}}else if(j>0)j=lps[j-1] else i++;return matches};fun numberOfWays(s:String,t:String,k:Long):Int{val n=s.length;if(n==1)return if(s==t&&k==0L)1 else 0;val matches=rotationMatches(s,t);val matrix=power(k,n);val same=matrix[0][0];val other=matrix[1][0];val answer=if(s==t)same+(matches-1L)*other else matches*other;return (answer%mod).toInt()} }
